<?php
$zipData = base64_decode('');
file_put_contents('deploy_final_fix.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_final_fix.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_final_fix.zip');
    
    $viewsPath = __DIR__ . '/../storage/framework/views';
    $files = glob($viewsPath . '/*.php');
    if ($files) {
        foreach ($files as $file) {
            if (is_file($file)) unlink($file);
        }
    }
    echo '<h1>Perfect!</h1>';
    echo '<p>Cancel button works, Page Access updates live, and header colors are perfect!</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>